def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ratio = np.divide(remaining, bins, out=np.zeros_like(bins, dtype=float), where=bins>0)
    score = -np.abs(np.sin(np.pi * ratio)) - 0.5 * np.abs(ratio - 0.618)
    return np.where(remaining >= 0, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_buffer = 0.05 * bins
    relative_deviation = (remaining - target_buffer) / (bins + 1e-8)
    score = -(relative_deviation ** 2)
    return np.where(remaining >= 0, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_buffer = 0.05 * bins
    score = -np.abs(remaining - target_buffer)
    return np.where(remaining >= 0, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_buffer = 0.075 * bins
    relative_deviation = (remaining - target_buffer) / (bins + 1e-8)
    score = -np.exp(np.square(relative_deviation))
    return np.where(remaining >= 0, score, -np.inf)
